const query = $('GET – Poll Resultado').first()?.json?.query ?? {};
const jobId = (query.jobId ?? '').trim();
if (!jobId) return [{ json: { status:'error', message:'jobId obrigatório' } }];
const row = $input.first()?.json ?? {};
if (!row.result) return [{ json: { status:'processing' } }];
const r = row.result;
const parsed = typeof r === 'string' ? JSON.parse(r) : r;
return [{ json: { status:'done', result: parsed } }];

const body = $input.first()?.json?.body ?? $input.first()?.json ?? {};
const message = (body.message ?? '').trim();
const history = Array.isArray(body.history) ? body.history : [];
const analysisContext = body.analysisContext ?? null;
const jobId = (body.jobId ?? '').trim();
if (!message) throw new Error('Mensagem vazia.');
if (!jobId)   throw new Error('jobId obrigatório.');
const hasUrl = /https?:\/\/[^\s]+/.test(message);
const references = Array.isArray(body.references) ? body.references.filter(u => /^https?:\/\//.test(u)) : [];
return [{ json: { message, history, analysisContext, jobId, references, needsAnalysis: analysisContext === null && hasUrl } }];

const data = $('Parse Request').first()?.json ?? {};
const msg = data.message ?? '';
const urlMatch = msg.match(/https?:\/\/[^\s,;!?]+/);
if (!urlMatch) throw new Error('URL não encontrada. Exemplo: https://centauro.com.br tênis de corrida');
const url = urlMatch[0].replace(/[.,;!?]+$/, '').trim();
const topic = msg.replace(url,'').replace(/\b(analise|sobre|o site|a url|verifique|quero analisar)\b/gi,' ').replace(/\s+/g,' ').trim();
if (!topic) throw new Error('Informe o tópico após a URL.');
return [{ json: { url, topic } }];

const psi = $input.first()?.json ?? {};
const lhr = psi.lighthouseResult ?? {};
const le  = psi.loadingExperience ?? {};
const aud = lhr.audits ?? {};
const met = le.metrics ?? {};
const scoreRaw = lhr.categories?.performance?.score;
return [{ json: {
  performance_score: scoreRaw != null ? Math.round(scoreRaw * 100) : null,
  fcp:  aud['first-contentful-paint']?.displayValue   ?? null,
  lcp:  aud['largest-contentful-paint']?.displayValue ?? null,
  tbt:  aud['total-blocking-time']?.displayValue      ?? null,
  cls:  aud['cumulative-layout-shift']?.displayValue  ?? null,
  si:   aud['speed-index']?.displayValue              ?? null,
  fcp_field: met.FIRST_CONTENTFUL_PAINT_MS?.category        ?? null,
  lcp_field: met.LARGEST_CONTENTFUL_PAINT_MS?.category      ?? null,
  inp_field: met.INTERACTION_TO_NEXT_PAINT?.category        ?? null,
  cls_field: met.CUMULATIVE_LAYOUT_SHIFT_SCORE?.category    ?? null,
  overall:   le.overall_category ?? null
}}];

const fanout = $('Query Fan-out v2').first()?.json ?? {};
const geo    = $('Prompt Mapper GEO').first()?.json ?? {};
const onPage = $('On-Page SEO Audit').first()?.json ?? {};
const cwv    = $('CorePulse CWV').first()?.json ?? {};
const psi    = $('Parse PSI').first()?.json ?? {};
const params = $('Extrair URL e Tópico').first()?.json ?? {};

const context = {
  url_analisada: params.url,
  topico: params.topic,
  query_fanout: {
    fanout_queries:   fanout.fanout_queries   ?? {},
    cited_sources:    fanout.cited_sources    ?? {},
    source_diversity: fanout.source_diversity ?? {},
    seo_summary:      fanout.seo_summary      ?? {}
  },
  geo_mapping: {
    summary:       geo.summary ?? '',
    total_prompts: geo.total   ?? 0,
    prompts:       (geo.prompts ?? []).slice(0, 10)
  },
  on_page_audit: onPage,
  cwv_data: {
    fonte: 'PageSpeed Insights API (laboratório + campo CrUX)',
    performance_score: psi.performance_score,
    metricas_lab: { fcp: psi.fcp, lcp: psi.lcp, tbt: psi.tbt, cls: psi.cls, si: psi.si },
    campo_crux:   { fcp: psi.fcp_field, lcp: psi.lcp_field, inp: psi.inp_field, cls: psi.cls_field, overall: psi.overall },
    corepulse_status: cwv.status ?? 'dispatched',
    corepulse_nota: 'Relatório CWV detalhado enviado por e-mail via CorePulse Analyzer.'
  }
};

// Inject accumulated feedback evolution notes into analysis context
const store = $getWorkflowStaticData('global');
const evo = store.seo_orch_evolution ?? null;
if (evo && evo.total_feedback > 0) {
  const notes = [];
  if (evo.sugestoes_recentes?.length) notes.push('Sugestões: ' + evo.sugestoes_recentes.join(' | '));
  if (evo.reclamacoes_recentes?.length) notes.push('Evitar: ' + evo.reclamacoes_recentes.join(' | '));
  if (notes.length) context.notas_evolucao_agente = notes.join(' // ');
}
// Include user-provided reference documents if any
const refsCtx = $('Buscar Referências').first()?.json?.referencesContext ?? '';
if (refsCtx) context.referencias_usuario = refsCtx;
return [{ json: { correlationContext: JSON.stringify(context, null, 2) } }];

const raw = ($input.first()?.json?.output ?? '').trim();
// Extrai JSON: tenta bloco de código primeiro, depois primeiro { até último }
let cleaned = raw;
const blockMatch = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
if (blockMatch) {
  cleaned = blockMatch[1].trim();
} else {
  const s = raw.indexOf('{');
  const e = raw.lastIndexOf('}');
  if (s >= 0 && e > s) cleaned = raw.slice(s, e + 1);
}
let analysisData;
try { analysisData = JSON.parse(cleaned); }
catch(err) { analysisData = { sumario:{ insights:['Não foi possível processar a análise. Tente novamente.'], nivel_impacto:'Médio' }, correlacoes:[], gaps_oportunidades:[], plano_acao:[], proximos_passos:[] }; }
const params = $('Extrair URL e Tópico').first()?.json ?? {};
const cwv    = $('CorePulse CWV').first()?.json ?? {};
const psi    = $('Parse PSI').first()?.json ?? {};
const analysisContext = {
  ...analysisData,
  url_analisada: params.url,
  topico:        params.topic,
  cwv_status:       cwv.status ?? 'dispatched',
  cwv_email_enviado: (cwv.status ?? '') === 'received',
  psi_score:   psi.performance_score ?? null,
  psi_lcp:     psi.lcp  ?? null,
  psi_fcp:     psi.fcp  ?? null,
  psi_cls:     psi.cls  ?? null,
  psi_tbt:     psi.tbt  ?? null,
  psi_overall: psi.overall ?? null,
  generated_at: new Date().toISOString()
};
return [{ json: { role:'assistant', messageType:'analysis', message:null, analysisContext } }];

const data    = $('Parse Request').first()?.json ?? {};
const message = data.message ?? '';
const history = data.history ?? [];
const ctx     = data.analysisContext ?? null;
const histText= history.length ? history.map(m=>(m.role==='user'?'Usuário':'Assistente')+': '+m.content).join('\n\n') : '(início da conversa)';
let ctxJSON;
if (!ctx || !ctx.url_analisada) {
  ctxJSON = JSON.stringify({ status: 'aguardando_analise', instrucao: 'Nenhuma análise foi realizada ainda. Oriente o usuário a informar uma URL completa (ex: https://decathlon.com.br) seguida do tópico/keyword para iniciar.' });
} else {
  ctxJSON = JSON.stringify({
    url_analisada: ctx.url_analisada,
    topico: ctx.topico,
    sumario: ctx.sumario,
    correlacoes: ctx.correlacoes,
    gaps_oportunidades: ctx.gaps_oportunidades,
    plano_acao: ctx.plano_acao,
    proximos_passos: ctx.proximos_passos,
    cwv_dados: {
      performance_score: ctx.psi_score,
      lcp: ctx.psi_lcp, fcp: ctx.psi_fcp, cls: ctx.psi_cls, tbt: ctx.psi_tbt,
      campo_geral: ctx.psi_overall,
      corepulse_email_enviado: ctx.cwv_email_enviado
    }
  }, null, 2);
}

// Read accumulated feedback evolution notes to guide the orchestrator
const store = $getWorkflowStaticData('global');
const evo = store.seo_orch_evolution ?? null;
let feedbackContext = '';
if (evo && evo.total_feedback > 0) {
  const parts = [];
  if (evo.sugestoes_recentes?.length) {
    parts.push('Sugestões dos usuários (incorpore nas respostas):\n' + evo.sugestoes_recentes.map(s => '- ' + s).join('\n'));
  }
  if (evo.reclamacoes_recentes?.length) {
    parts.push('Pontos a evitar (baseados em feedback negativo):\n' + evo.reclamacoes_recentes.map(s => '- ' + s).join('\n'));
  }
  if (parts.length) {
    feedbackContext = '\n\n---\n🔄 Notas de evolução do agente (' + evo.total_feedback + ' feedbacks acumulados):\n' + parts.join('\n\n');
  }
}
const refsCtx = $('Buscar Referências').first()?.json?.referencesContext ?? '';
return [{ json: { message, histText, ctxJSON, feedbackContext, referencesContext: refsCtx, url: ctx?.url_analisada??'', topico: ctx?.topico??'' } }];

