const data = $('Parse Request').first()?.json ?? {};
const convResult = $input.first()?.json ?? {};

// Normalize message for keyword-based signal detection
const raw = (data.message ?? '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const ctx = data.analysisContext ?? {};

// Feedback signal dictionaries
const signals = {
  sugestao: ['poderia','deveria','sugiro','prefiro','seria melhor','quero que','foca mais','aprofunde','proxima vez','sempre que','melhorar','adicionar','incluir','gostaria que','considere','melhore'],
  negativo: ['incorreto','errado','impreciso','ruim','fraco','nao gostei','inutil','irrelevante','superficial','generico','nao ajudou','confuso','faltou','faltando','incompleto','fraca'],
  positivo: ['otimo','excelente','perfeito','muito bom','gostei','util','preciso','correto','incrivel','ajudou','funciona','boa analise','parabens','exato','acertou']
};

let feedbackType = null, maxMatches = 0;
for (const [type, kws] of Object.entries(signals)) {
  const count = kws.filter(k => raw.includes(k)).length;
  if (count > maxMatches) { maxMatches = count; feedbackType = type; }
}

// Persist feedback and synthesize evolution notes
if (maxMatches > 0) {
  const store = $getWorkflowStaticData('global');
  if (!Array.isArray(store.seo_orch_feedback)) store.seo_orch_feedback = [];

  store.seo_orch_feedback.push({
    type: feedbackType,
    message: data.message,
    url: ctx.url_analisada ?? null,
    topico: ctx.topico ?? null,
    ts: new Date().toISOString()
  });

  // Keep rolling window of last 100 entries
  if (store.seo_orch_feedback.length > 100) {
    store.seo_orch_feedback = store.seo_orch_feedback.slice(-100);
  }

  // Synthesize evolution notes for future orchestrator calls
  const fb = store.seo_orch_feedback;
  store.seo_orch_evolution = {
    total_feedback: fb.length,
    last_updated: new Date().toISOString(),
    sugestoes_recentes: fb.filter(f => f.type === 'sugestao').slice(-8).map(f => f.message),
    reclamacoes_recentes: fb.filter(f => f.type === 'negativo').slice(-8).map(f => f.message)
  };
}

// Pass conversation result through unchanged
return [{ json: convResult }];

const refs = ($input.first()?.json?.references ?? []).slice(0, 3);
const pass  = $input.first()?.json ?? {};

if (refs.length === 0) {
  return [{ json: { ...pass, referencesContext: '' } }];
}

const MAX_CHARS = 4000;

// Transform Google Workspace URLs to export endpoints
function toFetchUrl(raw) {
  const doc   = raw.match(/docs\.google\.com\/document\/d\/([^\/\?#]+)/);
  if (doc)   return `https://docs.google.com/document/d/${doc[1]}/export?format=txt`;
  const sheet = raw.match(/docs\.google\.com\/spreadsheets\/d\/([^\/\?#]+)/);
  if (sheet) return `https://docs.google.com/spreadsheets/d/${sheet[1]}/export?format=csv`;
  return raw;
}

const fetched = [];
for (const rawUrl of refs) {
  const fetchUrl = toFetchUrl(rawUrl.trim());
  try {
    const resp = await $helpers.httpRequest({
      method: 'GET',
      url: fetchUrl,
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; SEO-Orchestrator/1.0)' },
      timeout: 15000,
    });
    const raw = typeof resp === 'string' ? resp : JSON.stringify(resp);
    const text = raw
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, MAX_CHARS);
    fetched.push({ url: rawUrl, content: text });
  } catch(e) {
    fetched.push({ url: rawUrl, content: `[Erro ao acessar: ${e.message}]` });
  }
}

const referencesContext =
  '\n\n---\n📎 Documentos de referência fornecidos pelo usuário:\n' +
  fetched.map((f, i) => `[Ref ${i + 1}] ${f.url}\n${f.content}`).join('\n\n');

return [{ json: { ...pass, referencesContext, referencesCount: fetched.length } }];
